let e=null;document.addEventListener("astro:page-load",()=>{e&&e.abort(),e=new AbortController;const t=e.signal,o=document.getElementById("back-to-top");if(!o)return;const l=()=>{(window.scrollY||document.documentElement.scrollTop)>500?o.classList.add("is-visible"):(o.classList.remove("is-visible"),o.blur())};window.addEventListener("scroll",l,{passive:!0,signal:t}),o.addEventListener("click",()=>{window.scrollTo({top:0,behavior:window.matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth"})},{signal:t}),l()});
